INSERT INTO nigeria_legal_sources (source_code,title,instrument_type,issuing_body,source_url,publication_or_commencement_date,authority_level,reliability_score,verification_status,scope,notes) VALUES ('NG-LUA-1978','Land Use Act','Act','Federal Republic of Nigeria','https://lawsofnigeria.placng.org/view2.php?sn=228','1978-03-29','Official text repository',97,'Verified','Nigeria','Land administration; primary statutory text surfaced through PLAC compendium; confirm current amendments and state-specific practice before legal reliance.') ON CONFLICT (source_code) DO NOTHING;
INSERT INTO nigeria_legal_sources (source_code,title,instrument_type,issuing_body,source_url,publication_or_commencement_date,authority_level,reliability_score,verification_status,scope,notes) VALUES ('NG-MMA-2007','Nigerian Minerals and Mining Act 2007','Act','Federal Ministry of Mines and Steel Development / Federal Republic of Nigeria','https://minesandsteel.gov.ng/wp-content/uploads/2023/03/Nigerian-Minerals-Mining-Act-2007.pdf','2007-03-29','Official government publication',99,'Verified','Nigeria','Mineral ownership, exploration and exploitation framework; ministry portal also publishes mining titles and application guidance.') ON CONFLICT (source_code) DO NOTHING;
INSERT INTO nigeria_legal_sources (source_code,title,instrument_type,issuing_body,source_url,publication_or_commencement_date,authority_level,reliability_score,verification_status,scope,notes) VALUES ('NG-EIA-1992','Environmental Impact Assessment Act','Act','Federal Republic of Nigeria / NESREA repository','https://nesrea.gov.ng/wp-content/uploads/2025/09/EIA-ACT.pdf','1992-12-10','Official government repository',98,'Verified','Nigeria','Prior environmental consideration and EIA requirements for qualifying public/private projects.') ON CONFLICT (source_code) DO NOTHING;
INSERT INTO nigeria_legal_sources (source_code,title,instrument_type,issuing_body,source_url,publication_or_commencement_date,authority_level,reliability_score,verification_status,scope,notes) VALUES ('NG-NDP-2023','Nigeria Data Protection Act 2023','Act','Nigeria Data Protection Commission','https://www.ndpc.gov.ng/ndp-act-2023/','2023-06-12','Official regulator',99,'Verified','Nigeria','Personal-data governance; applies to platform processing of identifiable persons and related records.') ON CONFLICT (source_code) DO NOTHING;
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-LAND-001','LAND_TENURE','State land administration and occupancy framework','Land within each State is vested in the Governor subject to the Land Use Act, with land held in trust and administered for the use and common benefit of Nigerians; urban and non-urban administration follows the Act’s allocation structure.','Statute',true,'Nigeria land diligence',98,'1978-03-29','Title/occupancy instrument; allocation evidence; survey/geospatial evidence; applicable state records','State Governor / relevant land administration authority','High: statutory administration must not be treated as proof that no customary or community interests exist.','Critical: title/occupancy position is a core investment-readiness gate.' FROM nigeria_legal_sources WHERE source_code='NG-LUA-1978' ON CONFLICT (rule_code) DO NOTHING;
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-LAND-002','LAND_TENURE','Separate urban and non-urban land administration','The Land Use Act distinguishes control and management of urban land from other land, with local-government functions applying to non-urban land subject to the Act.','Statute',true,'Nigeria land diligence',97,'1978-03-29','Jurisdiction classification; applicable allocation records','State land authority / Local Government as applicable','High: local context and community land interests require separate investigation.','High: competent authority depends on land classification and location.' FROM nigeria_legal_sources WHERE source_code='NG-LUA-1978' ON CONFLICT (rule_code) DO NOTHING;
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-MIN-001','MINERAL_RIGHTS','Mineral resources are federally controlled','The Nigerian Minerals and Mining Act places property in and control of mineral resources in the Government of the Federation and regulates lawful exploration and exploitation through the Act.','Statute',true,'Mineral-bearing assets in Nigeria',99,'2007-03-29','Mineral title; cadastral evidence; licence/lease records; environmental and land interface checks','Federal Ministry of Mines and Steel Development / Mining Cadastre Office','High: surface/occupancy interests and community impacts must be distinguished from mineral title.','Critical for mineral-backed asset representation.' FROM nigeria_legal_sources WHERE source_code='NG-MMA-2007' ON CONFLICT (rule_code) DO NOTHING;
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-MIN-002','MINERAL_RIGHTS','No mineral exploration or exploitation without lawful authority','Mineral exploration or exploitation requires authority under the Nigerian Minerals and Mining Act; the platform must not represent an unlicensed mineral claim as investment-ready.','Statute',true,'Mining and mineral assets',99,'2007-03-29','Valid mineral title and cadastral confirmation','Mining Cadastre Office / Ministry','High: community and affected-land issues remain separate diligence domains.','Critical investment gate.' FROM nigeria_legal_sources WHERE source_code='NG-MMA-2007' ON CONFLICT (rule_code) DO NOTHING;
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-ENV-001','ENVIRONMENTAL','Prior environmental consideration is required for qualifying projects','Public or private projects must consider environmental effects at an early stage, and projects likely to significantly affect the environment are subject to environmental impact assessment under the applicable Act.','Statute',true,'Qualifying public/private projects',98,'1992-12-10','Project classification; EIA screening/approval evidence where applicable','Competent environmental authority','High: environmental and community impacts should be surfaced before transaction clearance.','Critical for development and infrastructure assets.' FROM nigeria_legal_sources WHERE source_code='NG-EIA-1992' ON CONFLICT (rule_code) DO NOTHING;
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-DATA-001','DATA_PROTECTION','Personal-data processing must be lawful and accountable','The Nigeria Data Protection Act 2023 establishes the framework for protecting data-subject rights and regulating personal-data processing; ÒsánVault must apply privacy controls to identifiable owners, community representatives, reviewers and other natural persons.','Statute',true,'Platform processing of personal data',99,'2023-06-12','Lawful processing basis; privacy notice; access controls; retention/deletion controls; breach process','Nigeria Data Protection Commission','High where community/individual records contain personal data.','High: institutional diligence must not expose protected personal information.' FROM nigeria_legal_sources WHERE source_code='NG-NDP-2023' ON CONFLICT (rule_code) DO NOTHING;
INSERT INTO nigeria_rights_domains (domain_code,domain_name,institutional_position,primary_authority,source_rule_codes) VALUES ('LAND_TENURE','Land title, tenure and occupancy','Must be verified separately from community/customary claims and linked to location-specific authority records.','State land administration authority',ARRAY['NG-LAND-001','NG-LAND-002']) ON CONFLICT (domain_code) DO NOTHING;
INSERT INTO nigeria_rights_domains (domain_code,domain_name,institutional_position,primary_authority,source_rule_codes) VALUES ('CUSTOMARY_COMMUNITY','Customary and community interests','Must remain a dedicated diligence domain; absence of a platform record must never be treated as proof of absence of community interests.','Relevant State/local/traditional/community institutions as legally applicable',ARRAY['NG-LAND-001','NG-LAND-002']) ON CONFLICT (domain_code) DO NOTHING;
INSERT INTO nigeria_rights_domains (domain_code,domain_name,institutional_position,primary_authority,source_rule_codes) VALUES ('MINERAL_RIGHTS','Mineral exploration and exploitation rights','Separate federal mineral-title diligence from surface land/occupancy rights.','Mining Cadastre Office / Ministry of Mines and Steel Development',ARRAY['NG-MIN-001','NG-MIN-002']) ON CONFLICT (domain_code) DO NOTHING;
INSERT INTO nigeria_rights_domains (domain_code,domain_name,institutional_position,primary_authority,source_rule_codes) VALUES ('ENVIRONMENTAL','Environmental assessment and approvals','Environmental status must be assessed independently and can block development readiness.','Competent environmental authority',ARRAY['NG-ENV-001']) ON CONFLICT (domain_code) DO NOTHING;
INSERT INTO nigeria_rights_domains (domain_code,domain_name,institutional_position,primary_authority,source_rule_codes) VALUES ('DATA_PROTECTION','Personal-data and privacy rights','Public verification must minimize disclosure and keep sensitive personal data within controlled institutional access.','Nigeria Data Protection Commission',ARRAY['NG-DATA-001']) ON CONFLICT (domain_code) DO NOTHING;